WITH base AS (SELECT *, CONCAT(promo_code, ' ', channel) AS promo_code_channel FROM promotions WHERE channel IS DISTINCT FROM 'web'), attributed AS (SELECT e.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM base e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.ends_on >= pr.starts_on AND e.ends_on < pr.ends_on + INTERVAL 30 DAYS), latest AS (SELECT id, promo_code, starts_on, ends_on, discount_pct, promo_id, promotion_discount_pct FROM attributed QUALIFY ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY starts_on, id, promo_id) = 1), kept_keys AS (SELECT promo_code FROM latest INTERSECT SELECT promo_code FROM promotions WHERE discount_pct < 0.12), kept_rows AS (SELECT s.* FROM latest s JOIN kept_keys k ON s.promo_code = k.promo_code), base_promotions AS (SELECT *, CASE WHEN promo_code IN ('WELCOME5', 'VIP') THEN 'Priority' ELSE 'Other' END AS promo_code_group FROM kept_rows WHERE ends_on >= DATE '2023-05-23' AND discount_pct >= 0.24) SELECT promo_code, starts_on, ends_on, discount_pct, promo_id, promotion_discount_pct, promo_code_group, CASE WHEN promo_code RLIKE '^(WELCOME5|VIP)$' THEN 'CORE' WHEN promo_code RLIKE '^(SPRING10|BUNDLE)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS promo_code_zone FROM base_promotions ORDER BY discount_pct NULLS FIRST, promo_id DESC;
